import { ChangeDetectionStrategy, Component, booleanAttribute, input, model } from '@angular/core';

@Component({
  selector: 'aevko-collapsible',
  standalone: true,
  templateUrl: './collapsible.component.html',
  styleUrl: './collapsible.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoCollapsible {
  readonly label = input.required<string>();
  readonly open = model(false);
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly panelId = input('aevko-collapsible-panel');

  protected toggle(): void {
    if (!this.disabled()) this.open.update((value) => !value);
  }
}

:host {
  border-block: 1px solid var(--aevko-border, #c7c7c7);
  display: block;
}
button {
  align-items: center;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  display: flex;
  font: 700 1rem/1.3 var(--aevko-font-sans, sans-serif);
  justify-content: space-between;
  min-height: 2.75rem;
  padding: 0.75rem 0;
  text-align: start;
  width: 100%;
}
button:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.indicator {
  align-items: center;
  display: inline-flex;
  flex: none;
  line-height: 0;
  transition: transform 120ms ease;
}
.indicator.open {
  transform: rotate(90deg);
}
.indicator svg {
  height: 1rem;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
  width: 1rem;
}
.indicator:has(> :not(.fallback-icon)) > .fallback-icon {
  display: none;
}
div {
  padding: 0 0 1rem;
}
@media (prefers-reduced-motion: reduce) {
  .indicator {
    transition: none;
  }
}
